/**
 * Trust and credential stores are written privately, atomically and with fsync (docs/INVARIANTS.md I-LIFE-2 is not a rule
 * of its own: this pins audit finding A2). A power loss must not leave an empty store, and a write must not leave a
 * temporary file behind. Uses a throwaway HOME.
 */
import "./helpers/leak_guard.js";
import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

let home = "";
let previousHome: string | undefined;
before(() => { previousHome = process.env.HOME; home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-priv-home-")); process.env.HOME = home; });
after(() => { if (previousHome === undefined) delete process.env.HOME; else process.env.HOME = previousHome; fs.rmSync(home, { recursive: true, force: true }); });

function withFsyncCount<T>(run: () => T): { result: T; fsyncs: number } {
  const original = fs.fsyncSync;
  let fsyncs = 0;
  (fs as any).fsyncSync = (...args: Parameters<typeof fs.fsyncSync>) => { fsyncs++; return original(...args); };
  try { return { result: run(), fsyncs }; } finally { (fs as any).fsyncSync = original; }
}

test("setWorkspaceTrusted writes a 0600 store, fsynced, with no temporary file left", async () => {
  const { setWorkspaceTrusted, getTrustStorePath, isWorkspaceTrusted } = await import("../src/workspace_trust.js");
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-priv-ws-"));
  try {
    const { fsyncs } = withFsyncCount(() => setWorkspaceTrusted(ws, true));
    assert.ok(fsyncs >= 1, "the trust store is fsynced");
    const store = getTrustStorePath();
    assert.equal(fs.statSync(store).mode & 0o777, 0o600);
    assert.deepEqual(fs.readdirSync(path.dirname(store)).filter((n) => n.endsWith(".tmp")), []);
    delete process.env.NEXUS_TRUST_WORKSPACE;
    assert.equal(isWorkspaceTrusted(ws), true);
  } finally { fs.rmSync(ws, { recursive: true, force: true }); }
});

test("saveCredential writes a 0600 store, fsynced, with no temporary file left", async () => {
  const { saveCredential, credentialsPath } = await import("../src/credentials.js");
  const { fsyncs } = withFsyncCount(() => saveCredential("openrouter", { type: "api_key", key: "k-test" } as any));
  assert.ok(fsyncs >= 1, "the credential store is fsynced");
  const file = credentialsPath();
  assert.equal(fs.statSync(file).mode & 0o777, 0o600);
  assert.deepEqual(fs.readdirSync(path.dirname(file)).filter((n) => n.endsWith(".tmp")), []);
});
EOF
