    const plain = await sh(bridge(false), `echo x > ${outside}/plain.txt`);
    assert.equal(plain.exit, 0);
    assert.equal(fs.existsSync(path.join(outside, "plain.txt")), true, "baseline: the unsandboxed worker writes anywhere");
