289	/// Ends every command group the engine started, then exits.
290	async fn shutdown_and_exit(code: i32) {
291	    #[cfg(unix)]
292	    {
293	        let _ = tokio::task::spawn_blocking(|| runner::end_all_commands(CANCEL_GRACE)).await;
294	    }
295	    std::process::exit(code);
296	}
