298	fn parse_flexible_json(input: &str) -> Result<Value, String> {
299	    if let Ok(v) = serde_json::from_str::<Value>(input) {
300	        if let Value::String(ref s) = v {
301	            if let Ok(nested) = serde_json::from_str::<Value>(s) {
302	                return Ok(nested);
303	            }
304	        }
305	        return Ok(v);
306	    }
307	    let unescaped = input.replace(r#"\""#, "\"");
308	    if let Ok(v) = serde_json::from_str::<Value>(&unescaped) {
309	        return Ok(v);
310	    }
311	    let trimmed = input.trim_matches(|c| c == '\'' || c == '"');
312	    if let Ok(v) = serde_json::from_str::<Value>(trimmed) {
313	        return Ok(v);
314	    }
315	    Err(format!("Could not parse JSON arguments: {input}"))
316	}
317	
318	#[tokio::main]
319	async fn main() {
320	    let cli = Cli::parse();
321	    let workspace = std::fs::canonicalize(&cli.workspace).unwrap_or(cli.workspace);
322	
323	    match cli.command {
324	        Commands::Call { tool, args } => {
325	            let params = match parse_flexible_json(&args) {
326	                Ok(p) => p,
327	                Err(e) => {
328	                    eprintln!("Error: {e}");
329	                    std::process::exit(1);
330	                }
331	            };
332	            match execute_tool(&tool, params, &workspace) {
333	                Ok(res) => {
334	                    println!("{}", serde_json::to_string_pretty(&res).unwrap());
335	                }
336	                Err(e) => {
337	                    eprintln!("Error executing {tool}: {e}");
338	                    std::process::exit(1);
339	                }
340	            }
341	        }
342	        Commands::Rpc => {
343	            // If the client dies without closing stdin, the kernel delivers SIGTERM, which runs the same shutdown.
344	            #[cfg(target_os = "linux")]
345	            unsafe {
346	                libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGTERM);
347	            }
348	            run_rpc_async(&workspace).await;
349	        }
350	    }
351	}
