206	async fn run_rpc_async(workspace: &Path) {
207	    use std::sync::Arc;
208	    use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
209	
210	    let stdin = tokio::io::stdin();
211	    let reader = BufReader::new(stdin);
212	    let mut lines = reader.lines();
213	
214	    let stdout = Arc::new(tokio::sync::Mutex::new(tokio::io::stdout()));
215	    let ws = Arc::new(workspace.to_path_buf());
216	
217	    // The engine owns the commands it started: when its client goes away (stdin closes), or it is told to stop, every
218	    // command group still running (and every background process they left) is ended before it exits (REQ-SEC-106).
219	    #[cfg(unix)]
220	    {
221	        use tokio::signal::unix::{signal, SignalKind};
222	        for kind in [SignalKind::terminate(), SignalKind::hangup(), SignalKind::interrupt()] {
223	            if let Ok(mut stream) = signal(kind) {
224	                tokio::spawn(async move {
225	                    if stream.recv().await.is_some() {
226	                        shutdown_and_exit(143).await;
227	                    }
228	                });
229	            }
230	        }
231	    }
232	
233	    while let Ok(Some(line)) = lines.next_line().await {
234	        let trimmed = line.trim().to_string();
235	        if trimmed.is_empty() {
236	            continue;
237	        }
238	
239	        let stdout_clone = Arc::clone(&stdout);
240	        let ws_clone = Arc::clone(&ws);
241	
242	        tokio::spawn(async move {
243	            let response = match serde_json::from_str::<RpcRequest>(&trimmed) {
244	                Ok(req) => {
245	                    let method = req.method;
246	                    let params = req.params;
247	                    let id = req.id;
248	                    let key = id.as_ref().map(|v| v.to_string());
249	                    let exec_res = tokio::task::spawn_blocking(move || {
250	                        execute_request(&method, params, &ws_clone, key)
251	                    })
252	                    .await;
253	
254	                    match exec_res {
255	                        Ok(Ok(result)) => RpcResponse {
256	                            id,
257	                            result: Some(result),
258	                            error: None,
259	                        },
260	                        Ok(Err(err)) => RpcResponse {
261	                            id,
262	                            result: None,
263	                            error: Some(err),
264	                        },
265	                        Err(join_err) => RpcResponse {
266	                            id,
267	                            result: None,
268	                            error: Some(format!("Task execution failed: {join_err}")),
269	                        },
270	                    }
271	                }
272	                Err(e) => RpcResponse {
273	                    id: None,
274	                    result: None,
275	                    error: Some(format!("Invalid JSON-RPC request: {e}")),
276	                },
277	            };
