279	            if let Ok(json) = serde_json::to_string(&response) {
280	                let mut out = stdout_clone.lock().await;
281	                let _ = out.write_all(format!("{json}\n").as_bytes()).await;
282	                let _ = out.flush().await;
283	            }
284	        });
285	    }
286	    shutdown_and_exit(0).await;
287	}
