      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (VERIFIER_NOT_CONVERGING: ${t.convergence?.evidence ?? t.detail ?? "repeated verifier failures"}). Nothing is verified; the operator decides how to proceed.`,
    };
  }
  if (exec === "BLOCKED" && t.reason === "NEEDS_INPUT" && t.needsInput) {
    return {
      heading: "TURN BLOCKED - NEEDS INPUT",
      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (NEEDS_INPUT ${t.needsInput.id}: ${t.needsInput.prompt}). Resume with --answer ${t.needsInput.id}=approve or ${t.needsInput.id}=decline.${t.furtherNeedsInput?.length ? ` ${t.furtherNeedsInput.length} more question(s) wait behind it: ${t.furtherNeedsInput.map((q) => q.id).joi
    };
  }
  if (exec === "BLOCKED" && t.reason === "TOOL_CALL_LOOP") {
    return {
      heading: "TURN BLOCKED - REPEATED TOOL CALL",
      return { heading: "TASK COMPLETED - REGRESSION FREE", line: `execution=COMPLETED outcome=REGRESSION_FREE (${t.verification?.command})${tail}${contextTail(t)}` };
    case "NOT_REQUIRED":
      return { heading: "TURN ENDED - NO CHANGES TO VERIFY", line: `execution=COMPLETED outcome=NOT_REQUIRED modelStop=${t.modelStop}` };
    case "UNVERIFIED":
      return { heading: "TURN ENDED - UNVERIFIED", line: `execution=COMPLETED outcome=UNVERIFIED${tail}${evidenceTail(t)}` };
    default:
      if (t.reason === "REQUIREMENTS_INCOMPLETE") {
        return { heading: "TURN ENDED - REQUIREMENTS OPEN", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
      }
      return { heading: "TURN ENDED - NOT ESTABLISHED", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
  }

