    assert.deepEqual(ledger.requirements.map((r) => r.status), ["open", "open", "open"]);
    assert.equal(acks.length, 1);
    assert.match(acks[0].reason, /the turn ended before you decided/);
    assert.ok(!acks.some((a) => /declined/.test(a.reason ?? "")));
  });
