  return Object.entries(attributes).map(([key, value]) => {
    const val = Array.isArray(value)
      ? { arrayValue: { values: value.map((entry) => typeof entry === "string" ? { stringValue: entry } : typeof entry === "boolean" ? { boolValue: entry } : { intValue: 
