44	/**
45	 * Deterministic Flight Recorder for Agentic Code Execution
46	 * Records prompts, thoughts, tool calls, diffs, and durable state transitions into
47	 * append-only .flightlog archives for exact post-mortem replay and audit.
48	 */
49	export class FlightRecorder {
50	  private workspace: string;
51	  private flightId: string;
52	  private flightLogPath: string;
53	  private isRecording: boolean = false;
54	  private startTime: number = Date.now();
55	
56	  constructor(workspace: string, flightId?: string) {
57	    this.workspace = path.resolve(workspace);
58	    this.flightId = flightId || `flight-${new Date().toISOString().replace(/[:.]/g, "-")}-${randomUUID().slice(0, 6)}`;
59	    ensureGitExclude(this.workspace);
60	    const flightsDir = path.join(this.workspace, ".nexus", "flights");
61	    ensurePrivateDir(flightsDir);
62	    this.flightLogPath = path.join(flightsDir, `${this.flightId}.flightlog`);
63	  }
64	
65	  public getFlightId(): string {
66	    return this.flightId;
67	  }
68	
69	  public getLogPath(): string {
70	    return this.flightLogPath;
71	  }
72	
73	  public isSessionActive(): boolean {
74	    return this.isRecording;
75	  }
76	
77	  private appendEvent(type: FlightEventType, step: number | undefined, payload: Record<string, any>): FlightEvent {
78	    // Flightlogs are durable telemetry. Sanitize the complete event before its
79	    // only write path; a classifier failure must not fall through to plaintext
80	    // or prevent the authorized local capability from executing.
81	    const eventId = `evt-${randomUUID().slice(0, 8)}`;
82	    const timestamp = new Date().toISOString();
83	    let sanitizedPayload: Record<string, any>;
84	    try {
85	      sanitizedPayload = InformationFlowBoundary.getGlobalInstance().redactForTelemetry(payload);
86	    } catch {
87	      // Do not propagate classifier diagnostics that could echo inspected input.
88	      return {
89	        eventId,
90	        timestamp,
91	        type,
92	        step,
93	        payload: { recordingSkipped: true, reason: "sanitization_failed" },
94	      };
95	    }
96	    const event: FlightEvent = {
97	      eventId,
98	      timestamp,
99	      type,
100	      step,
101	      payload: sanitizedPayload,
102	    };
103	    try {
104	      appendPrivateFile(this.flightLogPath, JSON.stringify(event) + "\n");
105	    } catch {
106	      // Ignore flightlog append errors in restricted environments
107	    }
108	    return event;
109	  }
