    flight.recordTurnStart(1, "do the thing");
    flight.recordToolCall(1, "c1", "read_file", { path: "a.ts" });
    flight.recordToolResult(1, "c1", "read_file", true, "contents", 3);
    flight.recordFileDiff(2, "a.ts", "@@ -1 +1 @@\n-a\n+b");
