    assert.deepEqual(s.received("textDocument/didOpen").map((e) => [e.params.textDocument.uri, e.params.textDocument.version]), [[s.uri("a.ts"), 1], [s.uri("b.ts"), 1], [s.uri("c.ts"), 1]]);
  } finally {
    await s.close();
  }

